// neverError + fullResponse on the node above means a non-200 or a timeout
// arrives here as data rather than failing the execution. A keepalive that goes
// red on a single blip is noise, and the point is that it runs unattended.
//
// Reads only $input. Cross-node access ($('Some Node')) hangs indefinitely when
// the Code node runs in an external task runner, which is how this instance is
// configured -- executions sat in 'running' forever rather than failing.
const r = $input.first().json || {};
const status = r.statusCode ?? null;

return [{
  json: {
    ok: status === 200,
    statusCode: status,
    body: r.body ?? null,
    checkedAt: new Date().toISOString(),
  },
}];
